const items = $input.all();
const mensajeActual = $('📋 Set — Extrae datos del mensaje').item.json.mensaje_usuario;
const telefono = $('📋 Set — Extrae datos del mensaje').item.json.telefono;

let messages = [];

if (items.length > 0 && items[0].json.telefono) {
  const historial = items.slice(-30);
  for (const item of historial) {
    const rol = item.json.rol;
    const contenido = item.json.contenido;
    if (rol && contenido !== undefined && contenido !== null && contenido !== '') {
      messages.push({ role: String(rol), content: String(contenido) });
    }
  }
}

messages.push({ role: "user", content: String(mensajeActual) });

return [{ json: { telefono: telefono, mensaje_usuario: mensajeActual, messages: messages } }];

