const item = $input.first().json;
const textoCompleto = (item.content || []).find(c => c.type === 'text')?.text || '';
const marker = 'CITA_JSON:';
const idx = textoCompleto.indexOf(marker);

let texto_final = textoCompleto;
let cita = null;

if (idx !== -1) {
  texto_final = textoCompleto.slice(0, idx).trim();
  const jsonPart = textoCompleto.slice(idx + marker.length).trim();
  try { cita = JSON.parse(jsonPart); } catch (e) { cita = null; }
}

return [{ json: { texto_final, cita, tiene_cita: !!cita } }];

const eventos = $input.all().map(i => i.json);
const cita = $('🔧 Code — Detecta cita en respuesta').item.json.cita;
const DURACION_MIN = 45;
const MARGEN_MIN = 15;
const ZONA = 'Europe/Madrid';

function horarioClinica(weekday) {
  // weekday: 1=Lunes ... 7=Domingo
  if (weekday >= 1 && weekday <= 4) return { abre: 10, cierra: 20 };
  if (weekday === 5) return { abre: 10, cierra: 14 };
  return null; // cerrado sábado y domingo
}

const inicioSolicitado = DateTime.fromISO(`${cita.fecha}T${cita.hora}:00`, { zone: ZONA });
const finSolicitado = inicioSolicitado.plus({ minutes: DURACION_MIN });

const horario = horarioClinica(inicioSolicitado.weekday);
const horaInicio = inicioSolicitado.hour + inicioSolicitado.minute / 60;
const horaFinNum = finSolicitado.hour + finSolicitado.minute / 60;
const fueraDeHorario = !horario || horaInicio < horario.abre || horaFinNum > horario.cierra;

let ocupado = false;
if (!fueraDeHorario) {
  for (const ev of eventos) {
    const start = ev.start && (ev.start.dateTime || ev.start.date);
    const end = ev.end && (ev.end.dateTime || ev.end.date);
    if (!start || !end) continue;
    const evInicio = DateTime.fromISO(start).minus({ minutes: MARGEN_MIN });
    const evFin = DateTime.fromISO(end).plus({ minutes: MARGEN_MIN });
    if (inicioSolicitado < evFin && finSolicitado > evInicio) { ocupado = true; break; }
  }
}

const alternativas = [];
if (!fueraDeHorario && ocupado) {
  const [y, m, d] = cita.fecha.split('-').map(Number);
  for (let h = horario.abre; h < horario.cierra && alternativas.length < 3; h++) {
    for (const min of [0, 45]) {
      if (alternativas.length >= 3) break;
      const candidato = DateTime.fromObject({ year: y, month: m, day: d, hour: h, minute: min }, { zone: ZONA });
      const candidatoFin = candidato.plus({ minutes: DURACION_MIN });
      if (candidatoFin.hour + candidatoFin.minute / 60 > horario.cierra) continue;
      const choca = eventos.some(ev => {
        const start = ev.start && (ev.start.dateTime || ev.start.date);
        const end = ev.end && (ev.end.dateTime || ev.end.date);
        if (!start || !end) return false;
        const evInicio = DateTime.fromISO(start).minus({ minutes: MARGEN_MIN });
        const evFin = DateTime.fromISO(end).plus({ minutes: MARGEN_MIN });
        return candidato < evFin && candidatoFin > evInicio;
      });
      if (!choca) alternativas.push(candidato.toFormat('HH:mm'));
    }
  }
}

const hora_fin = finSolicitado.toFormat('HH:mm');
const motivo = fueraDeHorario ? 'fuera_de_horario' : (ocupado ? 'ocupado' : null);

return [{ json: { ...cita, libre: !fueraDeHorario && !ocupado, alternativas, hora_fin, motivo } }];

const c = $('🔧 Code — ¿Hueco libre?').item.json;
const texto_final = `¡Listo! ✅ Tu cita para ${c.tratamiento} ha quedado confirmada el ${c.fecha} a las ${c.hora}. Te llegará confirmación a ${c.email}. ¡Nos vemos en Clínica Sarabia!`;
return [{ json: { texto_final } }];

const c = $json;
const HORARIO_TEXTO = 'Lunes a jueves de 10:00 a 20:00, viernes de 10:00 a 14:00. Cerrado sábados y domingos.';

let texto_final;
if (c.motivo === 'fuera_de_horario') {
  texto_final = `Ese horario está fuera de nuestro horario de atención 😕 Abrimos: ${HORARIO_TEXTO} ¿Qué día y hora dentro de ese horario te vendría bien?`;
} else {
  const alt = (c.alternativas || []).join(', ');
  texto_final = alt
    ? `Ese horario ya está ocupado 😕 Tengo libres estos horarios ese mismo día: ${alt}. ¿Cuál te viene mejor?`
    : `Ese horario ya está ocupado y no quedan huecos libres ese día 😕 ¿Podrías decirme otro día que te venga bien?`;
}
return [{ json: { ...c, texto_final } }];
